<template><view class="page"><view class="profile-head"><image v-if="avatar" class="company-icon" :src="avatar" mode="aspectFill"/><view v-else class="company-icon">绿</view><text class="title">{{name}}</text><text class="muted">认证企业 · 合作中</text></view><view class="menu card"><view v-for="item in menu" :key="item.title" class="menu-row" @tap="open(item.url)"><text class="menu-icon">{{item.icon}}</text><text>{{item.title}}</text><text class="arrow">›</text></view></view><BottomNav role="enterprise" active="profile"/></view></template>
<script>import BottomNav from '../../components/BottomNav.vue';export default{components:{BottomNav},data(){return{avatar:'',name:'绿色生活品牌',menu:[{icon:'▣',title:'企业认证材料',url:'/pages/enterprise/certification'},{icon:'校',title:'合作学校',url:'/pages/enterprise/schools'},{icon:'⚙',title:'账号设置',url:'/pages/enterprise/settings'}]}},onShow(){this.avatar=uni.getStorageSync('enterprise_avatar')||'';this.name=uni.getStorageSync('enterprise_name')||'绿色生活品牌'},methods:{open(url){uni.navigateTo({url})}}}</script>
